"""Build an Arabic illustrated Spark setup guide. Console diagrams are labelled illustrations."""
from pathlib import Path
from html import escape as e
import base64,json
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/spark-setup'
OUT.mkdir(parents=True,exist_ok=True)
ZIP='https://raw.githubusercontent.com/mahmouddh1933-boop/Vokabeltrainer/d00c46cc64f3974184601336f8eba45910373a8c/downloads/Huroof-Firebase.zip'
steps=[]
def code(value):
 return '<div class="command"><code dir="ltr">'+e(value)+'</code><button class="copy" type="button">نسخ</button></div>'
def terminal(commands):
 return '<div class="terminal" dir="ltr"><div class="terminal-bar"><i></i><i></i><i></i><span>Command Prompt · رسم توضيحي للأوامر</span></div>'+''.join(code(c) for c in commands)+'</div>'
def console(selected,content,tab=''):
 return '''<div class="firebase" dir="ltr"><div class="firebase-head"><b>🔥 Firebase</b><span>letters-from-olive ▾</span><span class="spark">Spark · Free</span></div><div class="firebase-body"><aside><p>Project overview</p><p>Build ▾</p>'''+''.join('<div class="'+('selected' if s==selected else '')+'">'+s+'</div>' for s in ['Authentication','Firestore Database','Hosting'])+'''<hr><p>Usage and billing</p></aside><div class="firebase-main"><h3>'''+selected+'''</h3><div class="tabs">'''+tab+'''</div>'''+content+'''</div></div></div>'''
def add(title,lead,body,notes,kind='مخطط توضيحي — قد تختلف واجهة Firebase حسب اللغة والتحديثات'):
 steps.append(dict(title=title,lead=lead,body=body,notes=notes,kind=kind))
add('نزّل النسخة المجانية وافتح المجلد الصحيح','ابدأ من الكمبيوتر، واحتفظ بنسختك القديمة احتياطًا.',
 '''<div class="file-window" dir="ltr"><div class="file-bar">Downloads / Downloads → Huroof-Firebase.zip</div><div class="extract"><span>Huroof-Firebase.zip</span><strong class="focus">Extract all / Alle extrahieren</strong></div><div class="file-address"><span>📁 Huroof-Firebase</span><strong class="focus">cmd ↵</strong></div><div class="files"><div>📁 firebase-public <small>ملفات الموقع الجاهزة</small></div><div>📁 verification <small>أدوات اختبار محلية</small></div><div>📄 firebase.json <small>افتح نافذة الأوامر هنا</small></div><div>📄 firestore.rules</div><div>📄 firestore.indexes.json</div><div>📄 .firebaserc <small>قد يكون مخفيًا</small></div></div></div>''',
 '<p>١. حمّل <a href="'+ZIP+'">Huroof-Firebase.zip</a>.</p><p>٢. اضغط استخراج الكل، ثم افتح المجلد الناتج حتى ترى <bdi>firebase.json</bdi>.</p><p>٣. في Windows اكتب <bdi>cmd</bdi> في شريط عنوان المجلد واضغط Enter.</p><p class="tip">استخدم المجلد الجديد كاملًا. لا تحتاج إلى firebase init.</p>')
add('ثبّت الأدوات المجانية وسجّل دخول Firebase','نفّذ كل أمر وحده داخل المجلد الذي فتحته في الخطوة السابقة.',
 '<div class="tool-row"><a href="https://nodejs.org/en/download">Node.js LTS<br><small>22 أو أحدث متوافق</small></a><a href="https://adoptium.net/temurin/releases/?version=21">Java 21 JDK<br><small>للمحاكي واختبار القواعد</small></a></div>'+terminal(['node --version','npm --version','java -version','npm install -g firebase-tools','firebase login']),
 '<p>١. ثبّت Node.js وJava من الرابطين أعلاه، ثم أعد فتح نافذة الأوامر.</p><p>٢. افحص الأدوات بالأوامر الثلاثة الأولى.</p><p>٣. ثبّت Firebase CLI ثم نفّذ <bdi>firebase login</bdi>.</p><p class="tip">في المتصفح سجّل بحساب Google الذي يملك مشروع Firebase، ووافق على دخول CLI.</p>')
add('اختر Spark وفعّل البريد وكلمة السر','افتح console.firebase.google.com واختر مشروع letters-from-olive.',
 console('Authentication','''<div class="settings-title">Sign-in providers</div><div class="provider focus"><strong>Email/Password</strong><span>✎</span></div><div class="settings-box"><div>Email/Password <span class="toggle">Enable ✓</span></div><p>فعّل طريقة البريد وكلمة السر</p><button class="blue focus">Save / Speichern</button></div><div class="domain"><strong>Settings → Authorized domains</strong><p>letters-from-olive.web.app<br>letters-from-olive.firebaseapp.com</p></div>''','Users　 <b>Sign-in method</b>　 Settings'),
 '<p>١. تأكد أن خطة المشروع <bdi>Spark</bdi>، وهي المجانية.</p><p>٢. افتح <bdi>Authentication → Sign-in method</bdi>.</p><p>٣. فعّل <bdi>Email/Password</bdi> واحفظ.</p><p>٤. من Settings تأكد من وجود نطاقي الموقع في Authorized domains.</p><p class="tip">ابقَ على Spark دون ربط وسيلة دفع. الحصص المجانية محدودة وقد تتوقف الطلبات عند بلوغها.</p>')
add('استخدم قاعدة Firestore الحالية','لا تحذف الحسابات أو بيانات التعلم، ولا تنشئ قاعدة ثانية إذا كانت لديك قاعدة بالفعل.',
 console('Firestore Database','''<div class="database-title"><strong class="focus">(default)</strong><span>Cloud Firestore · Standard</span></div><div class="data-grid"><div><button class="plain">+ Start collection</button><p>users</p><small>سجلات التعلم الحالية</small></div><div class="empty-note">اترك بياناتك الحالية كما هي<br><small>ستنشر القواعد الجاهزة لاحقًا</small></div></div><div class="new-db">إذا لم تكن هناك قاعدة: Create database → Standard → (default) → Production mode</div>''','<b>Data</b>　 Rules　 Indexes　 Usage'),
 '<p>افتح <bdi>Firestore Database</bdi> من قائمة Build.</p><p>إذا ظهرت قاعدة <bdi>(default)</bdi>، استخدمها كما هي.</p><p>إذا لم توجد، أنشئ قاعدة Standard بالمعرّف <bdi>(default)</bdi> واختر وضع الإنتاج.</p><p class="tip">لن تحتاج إلى جعل القواعد عامة. ملفات النسخة الجديدة تحتوي القواعد المطلوبة.</p>')
add('اختبر قواعد الوصول قبل نشر الموقع','الاختبار محلي على مشروع تجريبي؛ لا يغيّر بيانات طلابك.',
 terminal(['npm ci --prefix verification','firebase emulators:exec --only firestore --project demo-huroof-access "npm run test:rules --prefix verification"'])+'''<div class="required"><b>النتيجة المطلوبة عندك: نجاح اختبار القواعد</b><p>إذا ظهر خطأ، توقّف وأرسل نصه قبل النشر. هذا ليس عرضًا لنتيجة اختبار ناجحة.</p></div>''',
 '<p>١. نفّذ أمر تثبيت أدوات الاختبار.</p><p>٢. انسخ الأمر الطويل كاملًا من هذا الدليل ونفّذه كسطر واحد.</p><p>٣. انتظر اكتمال الاختبار بنجاح.</p><p class="tip">تعذّر تنزيل المحاكي الرسمي في بيئة التجهيز بسبب حجب HTTP 403؛ لذلك يلزم تشغيل هذا الاختبار عندك.</p>')
add('انشر ملفات الموقع والقواعد الجديدة','نفّذ هذا الأمر فقط بعد نجاح اختبار القواعد.',
 terminal(['firebase deploy --only "firestore,hosting" --project letters-from-olive'])+'''<div class="result-url"><small>العنوان المتوقع بعد نجاح النشر — ليس إعلانًا بأن النشر تم</small><a href="https://letters-from-olive.web.app">https://letters-from-olive.web.app</a></div><div class="replace"><div>📁 firebase-public<br><small>يستبدل ملفات الموقع</small></div><span>＋</span><div>📄 firestore.rules<br><small>يحدّث قواعد الوصول</small></div></div>''',
 '<p>تنشر النسخة المجانية <bdi>firestore,hosting</bdi> فقط.</p><p>حسابات Authentication وتقدّم المتعلمين تبقى في المشروع نفسه.</p><p>بعد النجاح افتح رابط الموقع.</p><p>إذا سبق نشر وظائف مدفوعة، راجع إيقافها وخطة المشروع في الدليل النصي؛ هذا النشر لا يحذفها.</p><p class="tip">قد لا يفتح حساب المدير الدروس حتى تكمل منح الصلاحية في الخطوتين التاليتين.</p>')
add('أنشئ حسابك وأكّد بريدك، ثم انسخ UID','حساب المدير في التطبيق له بريد وكلمة سر؛ صلاحية الإدارة تُربط بمعرّف UID الخاص به.',
 '''<div class="account-flow"><div><b>داخل التطبيق</b><p>سجّل ببريدك الإداري<br>ثم افتح رسالة التأكيد</p><span class="green-chip">أعد التحقق</span></div><span class="flow-arrow">←</span><div><b>داخل Firebase Console</b><p>Authentication → Users<br>ابحث عن البريد نفسه</p></div></div>'''+console('Authentication','''<div class="user-table"><div class="table-head">Identifier <span>User UID</span></div><div class="table-row"><span>بريدك الإداري</span><strong class="focus">UID الخاص بحسابك　⧉</strong></div></div><p class="uid-tip" dir="rtl">اضغط زر النسخ بجانب UID الحقيقي في حسابك.<br>النص في هذه الصورة توضيحي، وليس UID صالحًا للنسخ.</p>''','<b>Users</b>　 Sign-in method　 Settings'),
 '<p>١. سجّل الدخول بحسابك، أو أنشئه إن لم يكن موجودًا.</p><p>٢. أكّد البريد من الرسالة، ثم اضغط «أعد التحقق».</p><p>٣. في Firebase افتح Authentication → Users.</p><p>٤. ابحث عن بريدك وانسخ <bdi>User UID</bdi>.</p><p class="tip">ظهور رسالة «البريد غير مضاف» قبل تهيئة الإدارة أمر متوقع.</p>')
add('امنح حسابك صلاحية المدير مرة واحدة','هذه أهم خطوة: اسم المجموعة ثابت، ومعرّف المستند هو UID حسابك الحقيقي.',
 console('Firestore Database','''<div class="role-dialog"><h4>Add a document</h4><label>Collection ID</label><div class="input focus">oliveFreeAdmins</div><small class="next-hint">Next / التالي →</small><label>Document ID</label><div class="input focus placeholder" dir="rtl">الصق UID الذي نسخته من حسابك</div><div class="field-row"><div><label>Field</label><strong class="input focus">enabled</strong></div><div><label>Type</label><strong class="input focus">boolean ▾</strong></div><div><label>Value</label><strong class="input focus">true ▾</strong></div></div><button class="blue focus">Save / Speichern</button></div>''','<b>Data → Start collection</b>'),
 '<p>١. افتح Firestore → Data → Start collection.</p><p>٢. اسم المجموعة: <bdi>oliveFreeAdmins</bdi>، ثم اضغط Next / التالي.</p><p>٣. Document ID: الصق UID حسابك، وليس البريد.</p><p>٤. أضف <bdi>enabled</bdi> من نوع <bdi>boolean</bdi> بقيمة <bdi>true</bdi> ثم احفظ.</p><p class="tip">لا تكتب true كنص، ولا تمنح هذه الصلاحية لحساب طالب.</p>')
add('افتح لوحة الإدارة وأضف إيميلات الطلاب','أعد تحميل الموقع بعد منح الصلاحية، ثم افتح لوحة الإدارة من القائمة أو قائمة الحساب.',
 '''<div class="actual-frame"><img src="images/admin-demo.png" alt="لوحة الإدارة الفعلية مع بيانات تجريبية في المحاكي المحلي"></div>''',
 '<p>١. افتح <a href="https://letters-from-olive.web.app/admin.html">صفحة لوحة الإدارة</a>.</p><p>٢. اكتب إيميل الطالب واضغط «إضافة إلى القائمة».</p><p>٣. يفتح الطالب حسابه ويؤكد ملكية بريده.</p><p>٤. أضف أيضًا إيميلات أصحاب الحسابات القديمة.</p><p class="tip">حد الجهازين إرشادي داخل الواجهة. تعطيل السماح للإيميل يمنع وصول الحساب إلى بياناته عبر قواعد Firestore.</p>',
 'لقطة فعلية لواجهة التطبيق من المحاكي المحلي؛ جميع بياناتها تجريبية، وليست من حسابك')
