css='@font-face{font-family:Arabic;src:url(data:font/woff;base64,'+font+')}@font-face{font-family:Latin;src:url(data:font/woff2;base64,'+latin+')}'+css
sections=[]
for i,s in enumerate(steps,1):
 sections.append(f'''<section class="guide-step" id="step-{i}"><div class="brand-line"><b>حروف من الزيتون · دليل الإعداد المجاني</b><span class="page-number">{i:02d} / 09</span></div><div class="step-title"><span class="step-number">{str(i).translate(str.maketrans('0123456789','٠١٢٣٤٥٦٧٨٩'))}</span><h1>{s['title']}</h1></div><p class="lead">{s['lead']}</p><div class="content"><div class="notes">{s['notes']}</div><div class="visual">{s['body']}<div class="kind">{s['kind']}</div></div></div><div class="footer"><span>إعداد الأستاذ محمود بركات</span><span>Spark · دون Cloud Functions · دون وسيلة دفع</span></div></section>''')
html='''<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>دليل الإعداد المجاني بالصور · حروف من الزيتون</title><style>'''+css+'''</style><body><nav class="guide-toolbar"><b>دليل Firebase Spark بالصور</b><div><a href="../../downloads/Huroof-Spark-Setup-AR.pdf">تحميل PDF</a>　 <a href="'''+ZIP+'''">تحميل التطبيق المجاني</a>　 <button onclick="window.print()">طباعة</button></div></nav><p class="mobile-note">يمكن تكبير الصور أو فتح PDF لقراءة الخطوات بسهولة على الهاتف. أمثلة نافذة الأوامر في الدليل لويندوز.</p>'''+''.join(sections)+'''<section class="guide-bottom"><b>ملاحظات قبل البدء</b><p>لم ينشر هذا الدليل أي تغييرات على مشروعك. الحصص المجانية محدودة، وقد تتوقف بعض الطلبات عند بلوغها. قائمة الإيميلات وعزل بيانات الحسابات يعتمدان على قواعد Firestore؛ حد الجهازين إرشادي داخل التطبيق وليس منعًا تقنيًا صارمًا. إنشاء حساب Authentication لا يعني السماح له بفتح الدروس.</p><p>إذا سبق أن نشرت وظائف النسخة المدفوعة أو فعّلت Blaze، راجع إيقافها وخطة المشروع وفق <a href="../../ADMIN-SETUP-AR.md">الدليل النصي</a>؛ رفع هذه الملفات وحده لا يحذف خدمات مدفوعة موجودة.</p></section><script>document.querySelectorAll('.copy').forEach(b=>b.onclick=async()=>{const text=b.previousElementSibling.textContent;try{await navigator.clipboard.writeText(text)}catch(_){const t=document.createElement('textarea');t.value=text;document.body.append(t);t.select();document.execCommand('copy');t.remove()}b.textContent='نُسخ';setTimeout(()=>b.textContent='نسخ',1800)});</script></body></html>'''
(OUT/'index.html').write_text(html)
(OUT/'steps.json').write_text(json.dumps([{'step':i,'title':s['title'],'image':f'images/step-{i:02d}.png'} for i,s in enumerate(steps,1)],ensure_ascii=False,indent=2)+'\n')
print('Guide HTML built: 9 pages; Firebase diagrams labelled; real local app capture labelled')

# Rendering is optional; the actual app screenshot above is a checked-in local demo capture.
import sys
if '--render' in sys.argv:
    from functools import partial
    from http.server import ThreadingHTTPServer, SimpleHTTPRequestHandler
    from threading import Thread
    from playwright.sync_api import sync_playwright
    from zipfile import ZipFile, ZIP_DEFLATED
    class QuietHandler(SimpleHTTPRequestHandler):
        def log_message(self, *args):
            pass
    server=ThreadingHTTPServer(('127.0.0.1',0),partial(QuietHandler,directory=str(ROOT)))
    worker=Thread(target=server.serve_forever,daemon=True)
    worker.start()
    try:
        with sync_playwright() as p:
            browser=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'])
            page=browser.new_page(viewport={'width':1440,'height':1180},device_scale_factor=1)
            failures=[]
            page.on('pageerror',lambda err:failures.append(str(err)))
            page.goto(f'http://127.0.0.1:{server.server_port}/docs/spark-setup/index.html')
            page.evaluate('document.fonts.ready')
            page.wait_for_function('Array.from(document.images).every(i=>i.complete&&i.naturalWidth>0)')
            assert page.locator('.guide-step').count()==9
            for number in range(1,10):
                section=page.locator(f'#step-{number}')
                section.scroll_into_view_if_needed()
                overlaps=section.evaluate('''el=>{const y=el.querySelector('.footer').getBoundingClientRect().top;return [...el.querySelectorAll('.notes,.visual')].filter(n=>n.getBoundingClientRect().bottom>y-8).map(n=>n.className)}''')
                assert not overlaps,(number,overlaps)
                section.screenshot(path=str(OUT/f'images/step-{number:02d}.png'))
            page.emulate_media(media='print')
            pdf=ROOT/'downloads/Huroof-Spark-Setup-AR.pdf'
            page.pdf(path=str(pdf),width='1280px',height='1100px',print_background=True,margin={'top':'0','bottom':'0','left':'0','right':'0'})
            assert not failures,failures
            browser.close()
    finally:
        server.shutdown()
        server.server_close()
    bundle=ROOT/'downloads/Huroof-Spark-Setup-AR.zip'
    with ZipFile(bundle,'w',ZIP_DEFLATED) as archive:
        prefix='Huroof-Spark-Setup-AR/'
        for file in sorted(OUT.rglob('*')):
            if not file.is_file():
                continue
            name=file.relative_to(OUT).as_posix()
            if name=='index.html':
                content=file.read_text().replace('../../downloads/Huroof-Spark-Setup-AR.pdf','Huroof-Spark-Setup-AR.pdf').replace('../../ADMIN-SETUP-AR.md','ADMIN-SETUP-AR.md')
                archive.writestr(prefix+name,content)
            else:
                archive.write(file,prefix+name)
        archive.write(pdf,prefix+pdf.name)
        archive.write(ROOT/'ADMIN-SETUP-AR.md',prefix+'ADMIN-SETUP-AR.md')
    with ZipFile(bundle) as archive:
        assert archive.testzip() is None
    print('Verified: 9 PNG pages without footer overlap, a PDF and an offline HTML guide ZIP')
